import{_ as e,o as a,c as r,a5 as o}from"./chunks/framework.BZzouRtU.js";const d="/study/images/game/game-loop-and-time.svg",g=JSON.parse('{"title":"ゲームループと時間 — 入力・更新・描画を繰り返す","description":"","frontmatter":{"title":"ゲームループと時間 — 入力・更新・描画を繰り返す","study":{"source":"新規執筆","section":"reference","format":"article","status":"published","domain":"game","summary":"プレイヤーの移動を例に、入力、状態の更新、描画、フレームとFPS、経過時間、可変更新と固定更新の役割を説明する。","aliases":["ゲームループ","game loop","フレーム","FPS","フレームタイム","delta time","deltaTime","dt","Update","FixedUpdate","固定更新","可変更新","入力","押し始め"],"verification":"Unity 6.0のUpdate・FixedUpdate・Time.deltaTimeと、ゲームループの既存詳解に照合（2026-11-07）"}},"headers":[],"relativePath":"game/basics/game-loop-and-time.md","filePath":"game/basics/game-loop-and-time.md"}'),n={name:"game/basics/game-loop-and-time.md"};function i(s,t,m,c,h,l){return a(),r("div",null,[...t[0]||(t[0]=[o('<h1 id="ゲームループと時間-—-入力・更新・描画を繰り返す" tabindex="-1">ゲームループと時間 — 入力・更新・描画を繰り返す <a class="header-anchor" href="#ゲームループと時間-—-入力・更新・描画を繰り返す" aria-label="Permalink to &quot;ゲームループと時間 — 入力・更新・描画を繰り返す&quot;">​</a></h1><p>移動キーを押している間、プレイヤーの位置は少しずつ変わり、画面も更新されます。入力を受け取り、ゲームの状態を変え、画像を作る処理を繰り返す仕組みが<strong>ゲームループ</strong>です。エンジンを使うときは、その繰り返しの中から自分の処理が呼ばれます。<a href="https://docs.unity3d.com/6000.0/Documentation/ScriptReference/MonoBehaviour.Update.html" target="_blank" rel="noreferrer">UnityのUpdate</a> · <a href="/study/game/basics/game-engine-basics.html">ゲームエンジンの役割</a></p><h2 id="入力、状態、表示する画像" tabindex="-1">入力、状態、表示する画像 <a class="header-anchor" href="#入力、状態、表示する画像" aria-label="Permalink to &quot;入力、状態、表示する画像&quot;">​</a></h2><table tabindex="0"><thead><tr><th>段階</th><th>すること</th><th>プレイヤーを動かす例</th></tr></thead><tbody><tr><td><strong>入力を受け取る</strong></td><td>操作の状態やイベントを読む。</td><td>右方向が押されているかを調べる。</td></tr><tr><td><strong>状態を更新する</strong></td><td>ルールと経過時間に応じて値を変える。</td><td>位置を進め、HPやゲームの状態を更新する。</td></tr><tr><td><strong>描画する</strong></td><td>現在の状態をもとに画像を作る。</td><td>カメラから見たプレイヤーを描く。</td></tr></tbody></table><p><strong>状態</strong>は、その時点の位置、速度、HPなど、後の動作に必要なデータです。描画は、その状態から画像を作る処理です。画像を作り終えた後には、実際に表示へ渡す段階もあります。<a href="/study/graphics/basics/light-and-rendered-images.html">光から描画された画像へ</a> · <a href="/study/graphics/optimization/swap-chain-and-vsync.html">スワップチェーンとVSync</a></p><figure class="study-figure"><img src="'+d+'" alt="右方向の入力を受け取り、状態の位置を6m/sと0.02秒から0.12m進め、カメラから描画する。その繰り返しの中で、固定更新と描画の回数は別に数える。" width="760" height="442" loading="lazy"><figcaption>入力・更新・描画の関係を示す説明用の順序図です。実際のエンジンは処理をさらに分け、CPUとGPUの仕事を重ねる場合があります。<a href="/study/images/game/game-loop-and-time.svg" target="_blank" rel="noopener noreferrer">ゲームループの図を拡大</a></figcaption></figure><h2 id="一回の更新で、何秒進めるか" tabindex="-1">一回の更新で、何秒進めるか <a class="header-anchor" href="#一回の更新で、何秒進めるか" aria-label="Permalink to &quot;一回の更新で、何秒進めるか&quot;">​</a></h2><p>「更新のたびに位置を1増やす」とすると、同じ時間に更新する回数が変わったとき、進む距離も変わります。そこで、一定速度の移動なら<strong>速度 × 進める秒数</strong>を使います。1秒に6m進む場合、0.02秒の更新で進む距離は<code>6 × 0.02 = 0.12m</code>です。<a href="https://docs.unity3d.com/6000.0/Documentation/ScriptReference/Time-deltaTime.html" target="_blank" rel="noreferrer">Unityの経過時間を使う移動</a></p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>新しい位置 = 今の位置 + 速度 × 今回進める秒数</span></span></code></pre></div><table tabindex="0"><thead><tr><th>この一定速度の例での更新</th><th>合計の時間</th><th>合計の移動距離</th></tr></thead><tbody><tr><td>0.02秒で一回進める</td><td>0.02秒</td><td>0.12m</td></tr><tr><td>0.01秒で二回進める</td><td>0.02秒</td><td>0.06m + 0.06m = 0.12m</td></tr></tbody></table><p>今回進める時間を<strong>デルタタイム</strong>や<code>dt</code>と呼ぶことがあります。Unityの通常の<code>Update</code>から使う<code>Time.deltaTime</code>は、ゲームの時間を進めるための値で、時間倍率の影響も受けます。実際に経過した時間を調べる場合は、用途に合う時計を選びます。<a href="https://docs.unity3d.com/6000.0/Documentation/ScriptReference/Time-deltaTime.html" target="_blank" rel="noreferrer">Time.deltaTime</a> · <a href="https://docs.unity3d.com/6000.0/Documentation/ScriptReference/Time-unscaledDeltaTime.html" target="_blank" rel="noreferrer">Time.unscaledDeltaTime</a></p><h2 id="フレームとfps" tabindex="-1">フレームとFPS <a class="header-anchor" href="#フレームとfps" aria-label="Permalink to &quot;フレームとFPS&quot;">​</a></h2><p>描画や画面の更新を一回ずつ数えるとき、その一回を<strong>フレーム</strong>と呼びます。<strong>FPS</strong>は一秒あたりのフレーム数です。均等な間隔の60 FPSなら、一回の間隔は約16.7msです。同じ平均60 FPSでも間隔にばらつきがあると、動きの滑らかさは変わります。<a href="/study/graphics/optimization/frame-pacing.html">フレームタイムとフレームペーシング</a></p><p>CPU側で描画を準備する回数、GPUが画像を作る時刻、ディスプレイが更新する時刻を調べると、どこで待ちが発生したかを追えます。ゲーム内の状態を進める<strong>更新ステップ</strong>も、必要に応じて別に数えます。<a href="/study/graphics/optimization/input-to-display-latency.html">入力から画面に出るまで</a></p><h2 id="可変更新と固定更新" tabindex="-1">可変更新と固定更新 <a class="header-anchor" href="#可変更新と固定更新" aria-label="Permalink to &quot;可変更新と固定更新&quot;">​</a></h2><p><strong>可変更新</strong>では、更新に渡す時間刻みが変わります。<strong>固定更新</strong>では、設定した時間刻みで状態を進めます。例えば物理を0.02秒ずつ進め、描画はそれとは別の頻度で行う構成があります。Unityでは<code>Update</code>と<code>FixedUpdate</code>がこうした処理の入口です。<code>FixedUpdate</code>は、一つの描画フレームの間に0回、1回、複数回呼ばれる場合があります。<a href="https://docs.unity3d.com/6000.0/Documentation/ScriptReference/MonoBehaviour.FixedUpdate.html" target="_blank" rel="noreferrer">UnityのFixedUpdate</a></p><p>固定更新を使うと、物理に渡す時間刻みをそろえられます。結果を再現できるかどうかには、入力を適用するステップ、処理の順番、数値計算なども関わります。詳しい設計は、<a href="/study/game/patterns/game-loop-and-update.html">Game LoopとUpdate Method</a>と<a href="/study/game/basics/collisions-and-physics.html">衝突判定と物理</a>で扱います。</p><h2 id="押し続ける入力と、押し始める入力" tabindex="-1">押し続ける入力と、押し始める入力 <a class="header-anchor" href="#押し続ける入力と、押し始める入力" aria-label="Permalink to &quot;押し続ける入力と、押し始める入力&quot;">​</a></h2><p>キーやパッドの操作をゲームの動作へ割り当てる方法は、<a href="/study/game/basics/input-actions-and-devices.html">入力アクションと機器</a>で説明します。</p><p>移動では「いま押されているか」を使い、弾を一発だけ撃つ操作では「押し始めたか」を使うなど、必要な情報を選びます。固定更新が同じ描画フレーム内に複数回あるなら、一度受けた発射要求をどの更新で使い切るかも決めます。入力の取得時点と、状態へ適用した時点を追うと、意図した回数だけ動かせるかを確認できます。<a href="https://docs.unity3d.com/Packages/com.unity.inputsystem@1.11/manual/Actions.html" target="_blank" rel="noreferrer">Unity Input Systemのアクション</a> · <a href="/study/game/patterns/command-buffer-and-input.html">入力とCommand Buffer</a></p><p>具体的なゲーム全体への組み込みは、<a href="/study/game/shooter-design.html">小さなシューティングの設計</a>へ進みます。</p>',21)])])}const u=e(n,[["render",i]]);export{g as __pageData,u as default};
